import { useEffect, useMemo, useState } from 'react';

// ---- inlined from maze ----
/** Shared grid, seeded generators, flood fill and geometry for the maze family. */

const COLS = 40;
const ROWS = 24;

const CELLS = COLS * ROWS;
const N = 1, S = 2, W = 4, E = 8;
const DIRECTIONS = [N, S, W, E];
const SEED = 20260813;
const START = (ROWS - 1) * COLS;

/** How many trailing cells of an in-progress corridor or walk are kept for display. */
const CORRIDOR_CAP = 70;
const WALK_CAP = 200;

/** Wilson's takes tens of thousands of walk moves; record one frame per this many. */
const WALK_SAMPLE = 12;

interface GenStep {
  /** Edges opened at this step, as [from, to] cell index pairs. */
  carve: [number, number][];
  /** The algorithm's active set: its frontier, its corridor, or its current walk. */
  active: number[];
}

interface Generated {
  /** Per cell, a bitmask of open sides; -1 for a cell not yet in the maze. */
  cells: number[];
  steps: GenStep[];
}

/** mulberry32: a fixed seed keeps every maze identical across reloads. */
function seededRandom(seed: number): () => number {
  let state = seed;
  return () => {
    state = (state + 0x6d2b79f5) | 0;
    let t = Math.imul(state ^ (state >>> 15), 1 | state);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const opposite = (dir: number) => (dir === N ? S : dir === S ? N : dir === W ? E : W);

const neighbor = (i: number, dir: number) =>
  i + (dir === N ? -COLS : dir === S ? COLS : dir === W ? -1 : 1);

function legal(i: number, dir: number): boolean {
  const x = i % COLS;
  const y = (i / COLS) | 0;
  return dir === N ? y > 0 : dir === S ? y < ROWS - 1 : dir === W ? x > 0 : x < COLS - 1;
}

/** Opens the wall between two adjacent cells, admitting both to the maze. */
function carve(cells: number[], a: number, b: number): void {
  const dir = b === a + 1 ? E : b === a - 1 ? W : b === a + COLS ? S : N;
  if (cells[a] < 0) cells[a] = 0;
  if (cells[b] < 0) cells[b] = 0;
  cells[a] |= dir;
  cells[b] |= opposite(dir);
}

const emptyGrid = () => new Array<number>(CELLS).fill(-1);
const tail = (values: number[], cap: number) => values.slice(Math.max(0, values.length - cap));

interface Edge {
  index: number;
  direction: number;
  weight: number;
}

/** Random traversal and Prim's differ only in which frontier edge is taken next. */
function growFrontier(take: (frontier: Edge[], random: () => number) => Edge): Generated {
  const random = seededRandom(SEED);
  const cells = emptyGrid();
  const steps: GenStep[] = [];
  const frontier: Edge[] = [];

  cells[START] = 0;
  push(START);

  while (frontier.length) {
    const edge = take(frontier, random);
    const target = neighbor(edge.index, edge.direction);
    if (cells[target] >= 0) continue;
    carve(cells, edge.index, target);
    push(target);
    steps.push({ carve: [[edge.index, target]], active: frontierCells(frontier, cells) });
  }

  return { cells, steps };

  function push(i: number): void {
    for (const dir of DIRECTIONS) {
      if (legal(i, dir) && cells[neighbor(i, dir)] < 0) {
        frontier.push({ index: i, direction: dir, weight: random() });
      }
    }
  }
}

/** The still-unclaimed cells the frontier is reaching into — the halo around the maze. */
function frontierCells(frontier: Edge[], cells: number[]): number[] {
  const seen = new Set<number>();
  for (const edge of frontier) {
    const target = neighbor(edge.index, edge.direction);
    if (cells[target] < 0) seen.add(target);
  }
  return [...seen];
}

const generateRandomTraversal = (): Generated =>
  growFrontier((frontier, random) => {
    const i = (random() * frontier.length) | 0;
    const edge = frontier[i];
    frontier[i] = frontier[frontier.length - 1];
    frontier.pop();
    return edge;
  });

const generatePrims = (): Generated =>
  growFrontier((frontier) => {
    let best = 0;
    for (let i = 1; i < frontier.length; ++i) {
      if (frontier[i].weight < frontier[best].weight) best = i;
    }
    const edge = frontier[best];
    frontier[best] = frontier[frontier.length - 1];
    frontier.pop();
    return edge;
  });

function generateDepthFirst(): Generated {
  const random = seededRandom(SEED);
  const cells = emptyGrid();
  const steps: GenStep[] = [];
  const stack = [START];

  cells[START] = 0;

  while (stack.length) {
    const head = stack[stack.length - 1];
    const options = DIRECTIONS.filter((dir) => legal(head, dir) && cells[neighbor(head, dir)] < 0);
    if (!options.length) {
      stack.pop();
      steps.push({ carve: [], active: tail(stack, CORRIDOR_CAP) });
      continue;
    }
    const next = neighbor(head, options[(random() * options.length) | 0]);
    carve(cells, head, next);
    stack.push(next);
    steps.push({ carve: [[head, next]], active: tail(stack, CORRIDOR_CAP) });
  }

  return { cells, steps };
}

function generateWilsons(): Generated {
  const random = seededRandom(SEED);
  const cells = emptyGrid();
  const steps: GenStep[] = [];
  const onWalk = new Array<boolean>(CELLS).fill(false);
  const remaining = Array.from({ length: CELLS }, (_, i) => i);

  cells[remaining.pop() as number] = 0; // the last cell seeds the maze

  while (remaining.length) {
    const origin = remaining.pop() as number;
    if (cells[origin] >= 0) continue;

    const walk = [origin];
    onWalk[origin] = true;

    for (let moves = 0; ; ++moves) {
      const head = walk[walk.length - 1];
      const dir = DIRECTIONS[(random() * 4) | 0];
      if (!legal(head, dir)) continue;
      const next = neighbor(head, dir);

      if (onWalk[next]) {
        while (walk[walk.length - 1] !== next) onWalk[walk.pop() as number] = false;
      } else {
        walk.push(next);
        onWalk[next] = true;
      }

      if (cells[next] >= 0) break;
      if (moves % WALK_SAMPLE === 0) steps.push({ carve: [], active: tail(walk, WALK_CAP) });
    }

    const carved: [number, number][] = [];
    for (let i = 1; i < walk.length; ++i) {
      carve(cells, walk[i - 1], walk[i]);
      carved.push([walk[i - 1], walk[i]]);
    }
    for (const i of walk) onWalk[i] = false;
    // The commit frame keeps the walk on screen. Over half of Wilson's steps are commits,
    // so clearing it here leaves the walk flickering in and out and the algorithm unreadable.
    steps.push({ carve: carved, active: tail(walk, WALK_CAP) });
  }

  return { cells, steps };
}

function generateKruskals(): Generated {
  const random = seededRandom(SEED);
  const cells = emptyGrid();
  const steps: GenStep[] = [];
  const parent = Array.from({ length: CELLS }, (_, i) => i);
  const find = (i: number): number => (parent[i] === i ? i : (parent[i] = find(parent[i])));

  const edges: { a: number; b: number; weight: number }[] = [];
  for (let i = 0; i < CELLS; ++i) {
    if (legal(i, E)) edges.push({ a: i, b: neighbor(i, E), weight: random() });
    if (legal(i, S)) edges.push({ a: i, b: neighbor(i, S), weight: random() });
  }
  edges.sort((p, q) => p.weight - q.weight);

  for (const { a, b } of edges) {
    const rootA = find(a);
    const rootB = find(b);
    if (rootA === rootB) continue;
    parent[rootA] = rootB;
    carve(cells, a, b);
    steps.push({ carve: [[a, b]], active: [a, b] });
  }

  return { cells, steps };
}

interface Flood {
  /** Each cell's predecessor on the path back to the origin; the origin is its own. */
  parent: number[];
  /** Cell indices grouped by distance from the origin. */
  layers: number[][];
}

function floodFill(cells: number[], origin = START): Flood {
  const parent = new Array<number>(CELLS).fill(-1);
  const layers: number[][] = [[origin]];
  parent[origin] = origin;

  let layer = layers[0];
  while (layer.length) {
    const next: number[] = [];
    for (const i of layer) {
      for (const dir of DIRECTIONS) {
        if (!(cells[i] & dir)) continue;
        const j = neighbor(i, dir);
        if (parent[j] >= 0) continue;
        parent[j] = i;
        next.push(j);
      }
    }
    if (next.length) layers.push(next);
    layer = next;
  }

  return { parent, layers };
}

interface MazeNode {
  index: number;
  children: MazeNode[];
}

/** The same maze read as a rooted tree, which is what d3.tree() needs. */
function mazeTree(cells: number[], origin = CELLS - 1): MazeNode {
  const root: MazeNode = { index: origin, children: [] };
  const seen = new Set<number>([origin]);
  const queue = [root];

  for (let head = 0; head < queue.length; ++head) {
    const node = queue[head];
    for (const dir of DIRECTIONS) {
      if (!(cells[node.index] & dir)) continue;
      const j = neighbor(node.index, dir);
      if (seen.has(j)) continue;
      seen.add(j);
      const child: MazeNode = { index: j, children: [] };
      node.children.push(child);
      queue.push(child);
    }
  }

  return root;
}

const cellCenter = (i: number, cw: number): [number, number] => [
  ((i % COLS) + 0.5) * cw,
  (((i / COLS) | 0) + 0.5) * cw
];

function point(i: number, cw: number): string {
  const [x, y] = cellCenter(i, cw);
  return `${x.toFixed(1)},${y.toFixed(1)}`;
}

/** One path fragment per generation step, so a chart can join a prefix to draw progress. */
function stepPaths(steps: GenStep[], cw: number): string[] {
  return steps.map((s) => s.carve.map(([a, b]) => `M${point(a, cw)}L${point(b, cw)}`).join(''));
}

/** An ordered run of cells as a single polyline: the DFS corridor, or Wilson's walk. */
function polyPath(ordered: number[], cw: number): string {
  return ordered.map((i, k) => `${k ? 'L' : 'M'}${point(i, cw)}`).join('');
}

/** One path per flood layer: every cell drawn as a stub back toward its parent. */
function layerPath(layer: number[], parent: number[], cw: number): string {
  return layer.map((i) => `M${point(parent[i], cw)}L${point(i, cw)}`).join('');
}

const TICK_MS = 40;
const TARGET_TICKS = 300;
const HOLD_TICKS = 40;
const FRONTIER = '#e0538a';

export default function MazePrims({ width }: { width: number }) {
  const cellWidth = Math.max(1, width) / COLS;
  const height = Math.round(cellWidth * ROWS);

  const { steps } = useMemo(() => generatePrims(), []);
  const fragments = useMemo(() => stepPaths(steps, cellWidth), [steps, cellWidth]);

  // The SSR frame is the finished maze; the effect rewinds and replays generation.
  const [step, setStep] = useState(steps.length);

  useEffect(() => {
    const perTick = Math.max(1, Math.ceil(steps.length / TARGET_TICKS));
    const end = steps.length + perTick * HOLD_TICKS;
    setStep(0);
    const id = window.setInterval(() => setStep((s) => (s >= end ? 0 : s + perTick)), TICK_MS);
    return () => window.clearInterval(id);
  }, [steps.length]);

  const shown = Math.min(step, steps.length);
  const carved = useMemo(() => fragments.slice(0, shown).join(''), [fragments, shown]);
  const frontier = shown > 0 && shown < steps.length ? steps[shown - 1].active : [];

  if (width === 0) return null;

  return (
    <svg
      viewBox={`0 0 ${width} ${height}`}
      width="100%"
      height={height}
      role="img"
      aria-label="Maze grown by Prim's algorithm, which always takes the lowest weighted frontier edge"
    >
      <path
        d={carved}
        fill="none"
        stroke="var(--accent)"
        strokeWidth={cellWidth * 0.42}
        strokeLinecap="round"
        strokeLinejoin="round"
      />
      {frontier.map((i) => {
        const [cx, cy] = cellCenter(i, cellWidth);
        return <circle key={i} cx={cx} cy={cy} r={cellWidth * 0.24} fill={FRONTIER} />;
      })}
    </svg>
  );
}
